// npm run build:dex → src/dex/entries.generated.ts (docs/DEX_SPEC.md → Generated file).
import { writeFileSync } from 'fs';
import { join } from 'path';

import { buildEntries } from '../src/dex/buildEntries';

const entries = buildEntries();
const body = `// GENERATED by scripts/build-dex.ts — do not edit. Rules: docs/DEX_SPEC.md.
import type { EntryDef } from './types';

export const ENTRIES: EntryDef[] = ${JSON.stringify(entries, null, 2)};
`;
const out = join(__dirname, '..', 'src', 'dex', 'entries.generated.ts');
writeFileSync(out, body);
console.log(`Wrote ${entries.length} entries to ${out}`);
